<template><div class="page"><div class="page-head"><div><h2>竞品数据</h2><p>记录竞品价格、促销、卖点、交付与服务承诺，用于竞争风险诊断。</p></div><div><el-input-number v-model="companyId" :min="1" style="width:120px;margin-right:8px"/><el-button @click="load">查询</el-button><el-button type="primary" v-if="auth.has('competitor:write')" @click="visible=true">新增竞品</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="companyId" label="我方企业ID" width="100"/><el-table-column prop="competitorName" label="竞品公司"/><el-table-column prop="productName" label="产品方案" min-width="160"/><el-table-column prop="targetCustomer" label="目标客户"/><el-table-column prop="price" label="价格" width="100"/><el-table-column prop="priceUnit" label="单位"/><el-table-column prop="sellingPoint" label="卖点" min-width="160"/><el-table-column prop="promotion" label="促销"/><el-table-column prop="deliveryCycle" label="交付周期"/><el-table-column prop="riskLevel" label="风险" width="90"/><el-table-column prop="updatedDate" label="更新日期" width="110"/></el-table>
<el-dialog v-model="visible" title="新增竞品数据" width="620px"><el-form label-width="90px"><el-form-item label="企业ID"><el-input-number v-model="form.companyId" :min="1"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="竞品公司"><el-input v-model="form.competitorName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="产品方案"><el-input v-model="form.productName"/></el-form-item></el-col></el-row><el-form-item label="目标客户"><el-input v-model="form.targetCustomer"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="价格"><el-input-number v-model="form.price" :precision="2"/></el-form-item></el-col><el-col :span="12"><el-form-item label="价格单位"><el-input v-model="form.priceUnit"/></el-form-item></el-col></el-row><el-form-item label="核心卖点"><el-input v-model="form.sellingPoint"/></el-form-item><el-form-item label="主要弱点"><el-input v-model="form.weakness"/></el-form-item><el-form-item label="促销"><el-input v-model="form.promotion"/></el-form-item><el-form-item label="服务承诺"><el-input v-model="form.serviceCommitment"/></el-form-item><el-form-item label="更新日期"><el-date-picker v-model="form.updatedDate" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore();const rows=ref([]),loading=ref(false),visible=ref(false),companyId=ref(null);const form=ref({companyId:1,competitorName:'示例竞品',productName:'专业版',targetCustomer:'中型企业',price:999,priceUnit:'元/月',sellingPoint:'交付快、价格低',weakness:'高级能力较弱',promotion:'首年8折',deliveryCycle:'7天',serviceCommitment:'4小时响应',riskLevel:'MEDIUM',updatedDate:new Date().toISOString().slice(0,10)});async function load(){loading.value=true;try{rows.value=(await api.competitors(companyId.value?{companyId:companyId.value}:{}))||[]}finally{loading.value=false}}async function save(){await api.createCompetitor(form.value);ElMessage.success('保存成功');visible.value=false;load()}onMounted(load)</script>
